using System.ComponentModel.DataAnnotations;

namespace VitalTrek.API.IncidentResponse.Interfaces.Rest.Resources;

/// <summary>
///     Resource to request an external e-mail notification about an incident with a declared emergency. NotificationId is
///     generated by the client and reused when the request is retried; the server generates one when it is omitted.
///     The recipient must be an authorized staff address of the agency.
/// </summary>
public record SendNotificationResource(
    [Required(ErrorMessage = "RequiredNotificationRecipientEmail")]
    [StringLength(254, MinimumLength = 3, ErrorMessage = "RequiredNotificationRecipientEmail")] string RecipientEmail,
    Guid? NotificationId = null,
    string? RecipientType = null);
